// Scene values are grouped by condition and window. The same material, emitter or light
// record is shared wherever more than one scene uses it.
export type SkyKind = 'blizzard' | 'blowingDust' | 'blowingSnow' | 'clear' | 'cloudyHighAltitude' | 'cloudyMidAltitude' | 'cloudyLowAltitude' | 'drizzle' | 'flurries' | 'foggy' | 'freezingDrizzle' | 'freezingRain' | 'frigid' | 'hail' | 'haze' | 'heavyRain' | 'heavySnow' | 'hot' | 'hurricane' | 'isolatedThunderstorms' | 'mostlyClear' | 'mostlyCloudyHighAltitude' | 'mostlyCloudyMidAltitude' | 'mostlyCloudyLowAltitude' | 'partlyCloudyHighAltitude' | 'partlyCloudyMidAltitude' | 'partlyCloudyLowAltitude' | 'rain' | 'scatteredThunderstorms' | 'sleet' | 'smoky' | 'snow' | 'strongStorms' | 'sunFlurries' | 'sunShowers' | 'thunderstorms' | 'tropicalStorm' | 'wintryMix';
export type GradientName = 'default_high' | 'default_low' | 'default_mid' | 'dust' | 'haze' | 'hurricane' | 'overcast_high' | 'overcast_low' | 'overcast_mid' | 'rain' | 'rainheavy' | 'smoky' | 'snow' | 'snowheavy';
export type WindowClass = 'compact' | 'compactLandscape' | 'portraitRegular' | 'landscapeRegular' | 'ultrawide';
export type CloudArt = 'Altostratus_Blanket' | 'Altostratus_SingleL' | 'Altostratus_SingleS' | 'Cirrostratus_SingleL' | 'Cirrostratus_SingleS' | 'Cirrus_Blanket' | 'Cirrus_SingleL' | 'Cirrus_SingleS' | 'Cumulonimbus_BlanketL' | 'Cumulonimbus_BlanketS' | 'Cumulus_SingleL' | 'Cumulus_SingleM' | 'Nimbostratus_SingleL' | 'Stratus_Blanket' | 'Stratus_SingleL' | 'Wispy_Single';
export type SkyLayer = 'stars' | 'shootingStar' | 'sunBeams' | 'sunDisc' | 'sunHalo' | 'sunGhosts' | 'moon' | 'fringe' | 'rain' | 'nearParticles' | 'fog' | 'lightning'
  | 'cloudFlash' | 'snow' | 'sleet' | 'hail' | 'dust';
export type CloudFamily = 'cirrostratus' | 'cirrus' | 'altostratus' | 'wispy' | 'cumulus' | 'nimbus' | 'stratus';
export type Range = readonly [low: number, high: number];
export type Deck = readonly [
  family: CloudFamily, count: number, scale: Range, height: number, velocity: Range,
  emitter: readonly [x: number, y: number, z: number], art: CloudArt, offsetZ: number,
  seed: number, useLighting: boolean, variants: number,
];
export type Blanket = readonly [family: CloudFamily, size: number, rise: number, art: CloudArt,
  velocity: number, offsetZ: number, useLighting: boolean, variants: number];
export type Decks = readonly [Deck | null, Deck | null, Deck | null, Deck | null];
type Particles = readonly [count: number, speed: number, size: Range];
export interface Lightning {
  reach: number;
  strikeInterval: Range;
  branchCount: number;
  roughness: number;
  totalStrikeLength: number;
  growAmount: number;
  flashAmount: number;
  fadeAmount: number;
  glow: number;
  screenFlashProbability: number;
  screenFlashBrightness: Range;
  screenFlashFadeLength: number;
  cloudFlashProbability: number;
  // The bolt's width in scene units, and how many times wider it flashes.
  thickness: number;
  flashThickness: number;
  // How far either side of the bolt's foot its branches head, in scene units.
  branchSpread: number;
  // Branches thin away from when the bolt has grown until growAmount + branchFadeAmount
  // of the way through the strike (a share of it, though both are given in seconds).
  branchFadeAmount: number;
  // How bright the light flickering behind the clouds gets (see cloudFlash).
  cloudFlashBrightness: number;
}
// Falling rain as drawn on a wide window, in scene units and seconds. Drops fall for `life`
// from a line `offset` above the frame's centre, `angle` degrees off straight down (turned
// with the line), swaying `sway` [degrees, radians per second] either way. Each layer (the
// near one in front, the far one behind) spawns `rate` drops a second, falling at up to
// `speed`, `size` wide (and about four times as long), each at an opacity drawn between
// `alpha`'s two, within `spread` degrees of the fall.
export type RainLayer = readonly [rate: number, speed: number, size: Range, alpha: Range, spread: number];
export interface RainFall {
  life: number;
  angle: number;
  offset: number;
  sway: Range;
  front: RainLayer;
  back: RainLayer;
}
type Five<T> = readonly [T, T, T, T, T];
type RGBA = readonly [number, number, number, number];
export interface AirTint {
  near: readonly [string,string];
  noise: readonly [string,string];
  fringe: string;
}
export interface PrecipitationTint {
  rain: {front: readonly [string,string];back: readonly [string,string]};
  snow: {front: readonly [string,string];back: readonly [string,string]};
  sleet: {front: readonly [string,string];back: readonly [string,string]};
  hail: readonly [string,string];
}
export type LightKeyframe = readonly [elevation: number, pm: 0 | 1, sun: string, sunIntensity: number,
  ambient: string, ambientIntensity: number, fill: string, fillIntensity: number,
  cloudColors: Five<string>, brightness: Five<number>, stars: number, cloudAlpha: Five<number>,
  sunAngle: readonly [x: number, y: number, z: number], moonIntensity: number, moonRadius: number,
  moonColor: string, moonHorizon: string, precipitation: PrecipitationTint, air: AirTint];
type SkyColor = readonly [red: number, green: number, blue: number];
export type GradientStop = readonly [elevation: number, pm: 0 | 1, top: SkyColor, middle: SkyColor, bottom: SkyColor, stop: number];
export interface SkyLook {
  near: {rate:number;life:number;speed:number;size:Range;image:number;spread:number;noise:Range;spin:Range};
  noise: {count:number;life:number;size:Range;speed:number;spin:Range;start:RGBA;end:RGBA};
  fringe: {count:number;size:number;amplitude:number;frequency:number;speed:number;spin:number;emitter:readonly [number,number,number];y:number;color:RGBA};
  sky: GradientName;
  decks: Decks;
  blanket: Blanket | null;
  fps: number;
  wind: { rate: number; speed: number; size: Range; x: Range; y: Range; color: string };
  camera: { y: number; z: number; focal: number };
  moonScale: Range;
  layers: readonly SkyLayer[];
  collision: 'none' | 'rain' | 'snow' | 'hail';
  rain: readonly [front: Particles, back: Particles];
  snow: readonly [front: Particles, back: Particles];
  hail: Particles;
  sleet: readonly [front: readonly [count: number, speed: number], back: readonly [count: number, speed: number]];
  stars: readonly [number, number, number, number];
  rays: readonly [angle: number, color: string, count: number, length: Range, spread: number];
  ghosts: readonly [opacity: number, count: number, length: number, size: Range];
  rainbow: readonly [scale: number, opacity: number];
  lightning: Lightning;
  rainFall: RainFall;
  // Rain splashing on the panels' top edges: the odds that a near drop reaching an edge
  // splashes, and its droplets' size (scene units), life (seconds) and launch speed (units a
  // second).
  splash: { odds: number; size: Range; life: Range; speed: Range };
  fallAngle: number;
  collision_probability: number;
  light: readonly LightKeyframe[];
  // The light while the moon shows in the sky, where the kind has one: bluer by night, and through
  // twilight its own.
  moonLight?: readonly LightKeyframe[];
}
export type SunKeyframe = readonly [hour: number, position: readonly [x: number,y: number], rayAngle: number,
  rainbow: number, ghosts: number, color: string, irisLength: number, irisFrequency: number, irisAmplitude: number];

