function pairAt(index: number): TintPair {
  const pair = particleColors[index];
  if (!pair) throw new Error('A weather particle has an unknown color pair.');
  return pair;
}
function airTint(near: number, noise: number, fringe: string): AirTint {
  return {near: pairAt(near), noise: pairAt(noise), fringe};
}
function rainTint(rainFront: number, rainBack: number, snowFront: number, snowBack: number,
  sleetFront: number, sleetBack: number, hail: number): PrecipitationTint {
  return {
    rain: {front: pairAt(rainFront), back: pairAt(rainBack)},
    snow: {front: pairAt(snowFront), back: pairAt(snowBack)},
    sleet: {front: pairAt(sleetFront), back: pairAt(sleetBack)},
    hail: pairAt(hail),
  };
}

